use std::cell::RefCell;
use std::cmp::max;
use std::rc::{Rc, Weak};

#[derive(Debug)]
pub struct BOSTree {
    pub root_node: Option<Rc<RefCell<BOSNode>>>,
    pub cmp_function: BOSTreeCmpFunction,
    pub free_function: Option<BOSTreeFreeFunction>,
}

#[derive(Debug)]
pub struct BOSNode {
    pub left_child_count: u32,
    pub right_child_count: u32,
    pub depth: u32,
    pub left_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub right_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub parent_node: Option<Weak<RefCell<BOSNode>>>,
    pub key: String,
    pub data: Option<String>,
    pub weak_ref_count: u8,
    pub weak_ref_node_valid: u8,
}

pub type BOSTreeCmpFunction = fn(&str, &str) -> i32;
pub type BOSTreeFreeFunction = fn(&Rc<RefCell<BOSNode>>);

/// Compute the balance factor of a node: right_depth - left_depth.
fn bostree_balance(node: &BOSNode) -> i32 {
    let left_depth = node
        .left_child_node
        .as_ref()
        .map_or(0i32, |n| n.borrow().depth as i32 + 1);
    let right_depth = node
        .right_child_node
        .as_ref()
        .map_or(0i32, |n| n.borrow().depth as i32 + 1);
    right_depth - left_depth
}

/// Perform a right rotation at `p`. Returns the new subtree root (L).
///
///       P                     L
///   L        R     -->    c1      P
/// c1 c2                        c2     R
fn rotate_right(tree: &mut BOSTree, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    // Extract L
    let l = {
        let p_ref = p.borrow();
        Rc::clone(p_ref.left_child_node.as_ref().unwrap())
    };

    // Snapshot P's parent weak reference
    let p_parent_weak = { p.borrow().parent_node.clone() };

    // Re-point P's parent to L (or set L as new root)
    match p_parent_weak.as_ref().and_then(|w| w.upgrade()) {
        Some(pp) => {
            let mut pp_mut = pp.borrow_mut();
            let is_left = pp_mut
                .left_child_node
                .as_ref()
                .map_or(false, |n| Rc::ptr_eq(n, p));
            if is_left {
                pp_mut.left_child_node = Some(Rc::clone(&l));
            } else {
                pp_mut.right_child_node = Some(Rc::clone(&l));
            }
        }
        None => {
            tree.root_node = Some(Rc::clone(&l));
        }
    }

    // L inherits P's parent
    l.borrow_mut().parent_node = p_parent_weak;

    // Snapshot L's right child (c2) and its count
    let (c2, l_right_count) = {
        let l_ref = l.borrow();
        (l_ref.right_child_node.clone(), l_ref.right_child_count)
    };

    // P's left child becomes c2, and left child count becomes L's right child count
    {
        let mut p_mut = p.borrow_mut();
        p_mut.left_child_node = c2.clone();
        p_mut.left_child_count = l_right_count;
    }

    // c2's parent becomes P
    if let Some(ref c2_node) = c2 {
        c2_node.borrow_mut().parent_node = Some(Rc::downgrade(p));
    }

    // Update P's depth
    {
        let mut p_mut = p.borrow_mut();
        let p_left_depth = p_mut
            .left_child_node
            .as_ref()
            .map_or(0u32, |n| n.borrow().depth + 1);
        let p_right_depth = p_mut
            .right_child_node
            .as_ref()
            .map_or(0u32, |n| n.borrow().depth + 1);
        p_mut.depth = max(p_left_depth, p_right_depth);
        p_mut.parent_node = Some(Rc::downgrade(&l));
    }

    // L's right child becomes P
    {
        let mut l_mut = l.borrow_mut();
        l_mut.right_child_node = Some(Rc::clone(p));
        l_mut.right_child_count = {
            let p_ref = p.borrow();
            p_ref.left_child_count + p_ref.right_child_count + 1
        };
    }

    // Update L's depth
    {
        let mut l_mut = l.borrow_mut();
        let l_left_depth = l_mut
            .left_child_node
            .as_ref()
            .map_or(0u32, |n| n.borrow().depth + 1);
        let l_right_depth = l_mut
            .right_child_node
            .as_ref()
            .map_or(0u32, |n| n.borrow().depth + 1);
        l_mut.depth = max(l_left_depth, l_right_depth);
    }

    l
}

/// Perform a left rotation at `p`. Returns the new subtree root (R).
///
///       P                     R
///   L        R     -->    P      c2
///          c1 c2        L  c1
fn rotate_left(tree: &mut BOSTree, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    // Extract R
    let r = {
        let p_ref = p.borrow();
        Rc::clone(p_ref.right_child_node.as_ref().unwrap())
    };

    // Snapshot P's parent weak reference
    let p_parent_weak = { p.borrow().parent_node.clone() };

    // Re-point P's parent to R (or set R as new root)
    match p_parent_weak.as_ref().and_then(|w| w.upgrade()) {
        Some(pp) => {
            let mut pp_mut = pp.borrow_mut();
            let is_left = pp_mut
                .left_child_node
                .as_ref()
                .map_or(false, |n| Rc::ptr_eq(n, p));
            if is_left {
                pp_mut.left_child_node = Some(Rc::clone(&r));
            } else {
                pp_mut.right_child_node = Some(Rc::clone(&r));
            }
        }
        None => {
            tree.root_node = Some(Rc::clone(&r));
        }
    }

    // R inherits P's parent
    r.borrow_mut().parent_node = p_parent_weak;

    // Snapshot R's left child (c1) and its count
    let (c1, r_left_count) = {
        let r_ref = r.borrow();
        (r_ref.left_child_node.clone(), r_ref.left_child_count)
    };

    // P's right child becomes c1, and right child count becomes R's left child count
    {
        let mut p_mut = p.borrow_mut();
        p_mut.right_child_node = c1.clone();
        p_mut.right_child_count = r_left_count;
    }

    // c1's parent becomes P
    if let Some(ref c1_node) = c1 {
        c1_node.borrow_mut().parent_node = Some(Rc::downgrade(p));
    }

    // Update P's depth
    {
        let mut p_mut = p.borrow_mut();
        let p_left_depth = p_mut
            .left_child_node
            .as_ref()
            .map_or(0u32, |n| n.borrow().depth + 1);
        let p_right_depth = p_mut
            .right_child_node
            .as_ref()
            .map_or(0u32, |n| n.borrow().depth + 1);
        p_mut.depth = max(p_left_depth, p_right_depth);
        p_mut.parent_node = Some(Rc::downgrade(&r));
    }

    // R's left child becomes P
    {
        let mut r_mut = r.borrow_mut();
        r_mut.left_child_node = Some(Rc::clone(p));
        r_mut.left_child_count = {
            let p_ref = p.borrow();
            p_ref.left_child_count + p_ref.right_child_count + 1
        };
    }

    // Update R's depth
    {
        let mut r_mut = r.borrow_mut();
        let r_left_depth = r_mut
            .left_child_node
            .as_ref()
            .map_or(0u32, |n| n.borrow().depth + 1);
        let r_right_depth = r_mut
            .right_child_node
            .as_ref()
            .map_or(0u32, |n| n.borrow().depth + 1);
        r_mut.depth = max(r_left_depth, r_right_depth);
    }

    r
}

impl BOSTree {
    pub fn bostree_new(
        cmp_function: BOSTreeCmpFunction,
        free_function: Option<BOSTreeFreeFunction>,
    ) -> Self {
        BOSTree {
            root_node: None,
            cmp_function,
            free_function,
        }
    }

    pub fn bostree_node_count(&self) -> u32 {
        match self.root_node {
            Some(ref root) => {
                let root_ref = root.borrow();
                root_ref.left_child_count + root_ref.right_child_count + 1
            }
            None => 0,
        }
    }

    pub fn bostree_insert(&mut self, key: String, data: Option<String>) -> Rc<RefCell<BOSNode>> {
        // Handle empty tree case
        if self.root_node.is_none() {
            let new_node = Rc::new(RefCell::new(BOSNode {
                left_child_count: 0,
                right_child_count: 0,
                depth: 0,
                left_child_node: None,
                right_child_node: None,
                parent_node: None,
                key,
                data,
                weak_ref_count: 1,
                weak_ref_node_valid: 1,
            }));
            self.root_node = Some(Rc::clone(&new_node));
            return new_node;
        }

        let cmp_func = self.cmp_function;

        // Walk down the tree to find the insertion point, incrementing child counts
        let mut current = Rc::clone(self.root_node.as_ref().unwrap());
        loop {
            let cmp = cmp_func(&key, &current.borrow().key);
            if cmp < 0 {
                current.borrow_mut().left_child_count += 1;
                let has_left = { current.borrow().left_child_node.is_some() };
                if has_left {
                    let left = { Rc::clone(current.borrow().left_child_node.as_ref().unwrap()) };
                    current = left;
                } else {
                    break;
                }
            } else {
                current.borrow_mut().right_child_count += 1;
                let has_right = { current.borrow().right_child_node.is_some() };
                if has_right {
                    let right = { Rc::clone(current.borrow().right_child_node.as_ref().unwrap()) };
                    current = right;
                } else {
                    break;
                }
            }
        }

        // current is now the parent node where we insert the new child
        let new_node = Rc::new(RefCell::new(BOSNode {
            left_child_count: 0,
            right_child_count: 0,
            depth: 0,
            left_child_node: None,
            right_child_node: None,
            parent_node: Some(Rc::downgrade(&current)),
            key,
            data,
            weak_ref_count: 1,
            weak_ref_node_valid: 1,
        }));

        // Attach the new node
        {
            let cmp = cmp_func(&new_node.borrow().key, &current.borrow().key);
            let mut cur_mut = current.borrow_mut();
            if cmp < 0 {
                cur_mut.left_child_node = Some(Rc::clone(&new_node));
            } else {
                cur_mut.right_child_node = Some(Rc::clone(&new_node));
            }
        }

        // Check if depth changed: only if this is the first child
        let depth_changed = {
            let cur_ref = current.borrow();
            cur_ref.left_child_node.is_some() ^ cur_ref.right_child_node.is_some()
        };

        if depth_changed && current.borrow().parent_node.is_some() {
            // Increment parent's depth
            current.borrow_mut().depth += 1;

            // Bubble up, updating depths and rebalancing
            let mut node = Rc::clone(&current);
            loop {
                // Move to parent
                let parent = match node
                    .borrow()
                    .parent_node
                    .as_ref()
                    .and_then(|w| w.upgrade())
                {
                    Some(p) => p,
                    None => break,
                };

                let new_left_depth = parent
                    .borrow()
                    .left_child_node
                    .as_ref()
                    .map_or(0u32, |n| n.borrow().depth + 1);
                let new_right_depth = parent
                    .borrow()
                    .right_child_node
                    .as_ref()
                    .map_or(0u32, |n| n.borrow().depth + 1);
                let max_depth = max(new_left_depth, new_right_depth);

                let depth_unchanged = {
                    let p_ref = parent.borrow();
                    if p_ref.depth != max_depth {
                        drop(p_ref);
                        parent.borrow_mut().depth = max_depth;
                        false
                    } else {
                        true
                    }
                };

                if depth_unchanged {
                    break;
                }

                // Check AVL property
                if new_left_depth as i32 == new_right_depth as i32 + 2 {
                    // Left is two levels deeper: handle left-right case first
                    let left_child = { parent.borrow().left_child_node.clone() };
                    if let Some(ref lc) = left_child {
                        if bostree_balance(&lc.borrow()) > 0 {
                            rotate_left(self, lc);
                        }
                    }
                    node = rotate_right(self, &parent);
                } else if new_left_depth as i32 + 2 == new_right_depth as i32 {
                    // Right is two levels deeper: handle right-left case first
                    let right_child = { parent.borrow().right_child_node.clone() };
                    if let Some(ref rc) = right_child {
                        if bostree_balance(&rc.borrow()) < 0 {
                            rotate_right(self, rc);
                        }
                    }
                    node = rotate_left(self, &parent);
                } else {
                    node = Rc::clone(&parent);
                }
            }
        }

        new_node
    }

    pub fn bostree_remove(&mut self, node: &Rc<RefCell<BOSNode>>) {
        let mut bubble_up: Option<Rc<RefCell<BOSNode>>> = None;

        let has_both_children = {
            let n_ref = node.borrow();
            n_ref.left_child_node.is_some() && n_ref.right_child_node.is_some()
        };

        if has_both_children {
            // Node has children on both sides: find a replacement candidate
            let left_depth = node
                .borrow()
                .left_child_node
                .as_ref()
                .map_or(0u32, |n| n.borrow().depth);
            let right_depth = node
                .borrow()
                .right_child_node
                .as_ref()
                .map_or(0u32, |n| n.borrow().depth);

            let (candidate, bubble_start, lost_child): (
                Rc<RefCell<BOSNode>>,
                Rc<RefCell<BOSNode>>,
                Option<Rc<RefCell<BOSNode>>>,
            ) = if left_depth >= right_depth {
                // Bubble from left side: find rightmost node in left subtree
                node.borrow_mut().left_child_count -= 1;
                let mut candidate = {
                    Rc::clone(node.borrow().left_child_node.as_ref().unwrap())
                };
                while candidate.borrow().right_child_node.is_some() {
                    candidate.borrow_mut().right_child_count -= 1;
                    let next = {
                        Rc::clone(candidate.borrow().right_child_node.as_ref().unwrap())
                    };
                    candidate = next;
                }
                let lost = { candidate.borrow().left_child_node.clone() };

                // Detach candidate from its parent
                let bubble_start = {
                    let cand_ref = candidate.borrow();
                    cand_ref
                        .parent_node
                        .as_ref()
                        .and_then(|w| w.upgrade())
                        .unwrap()
                };
                {
                    let mut bs_mut = bubble_start.borrow_mut();
                    if bs_mut
                        .left_child_node
                        .as_ref()
                        .map_or(false, |n| Rc::ptr_eq(n, &candidate))
                    {
                        bs_mut.left_child_node = lost.clone();
                    } else {
                        bs_mut.right_child_node = lost.clone();
                    }
                }
                if let Some(ref lc) = lost {
                    lc.borrow_mut().parent_node =
                        Some(Rc::downgrade(&bubble_start));
                }
                (candidate, bubble_start, lost)
            } else {
                // Bubble from right side: find leftmost node in right subtree
                node.borrow_mut().right_child_count -= 1;
                let mut candidate = {
                    Rc::clone(node.borrow().right_child_node.as_ref().unwrap())
                };
                while candidate.borrow().left_child_node.is_some() {
                    candidate.borrow_mut().left_child_count -= 1;
                    let next = {
                        Rc::clone(candidate.borrow().left_child_node.as_ref().unwrap())
                    };
                    candidate = next;
                }
                let lost = { candidate.borrow().right_child_node.clone() };

                // Detach candidate from its parent
                let bubble_start = {
                    let cand_ref = candidate.borrow();
                    cand_ref
                        .parent_node
                        .as_ref()
                        .and_then(|w| w.upgrade())
                        .unwrap()
                };
                {
                    let mut bs_mut = bubble_start.borrow_mut();
                    if bs_mut
                        .left_child_node
                        .as_ref()
                        .map_or(false, |n| Rc::ptr_eq(n, &candidate))
                    {
                        bs_mut.left_child_node = lost.clone();
                    } else {
                        bs_mut.right_child_node = lost.clone();
                    }
                }
                if let Some(ref lc) = lost {
                    lc.borrow_mut().parent_node =
                        Some(Rc::downgrade(&bubble_start));
                }
                (candidate, bubble_start, lost)
            };

            // Anchor candidate into node's position
            {
                let node_parent_weak = { node.borrow().parent_node.clone() };
                match node_parent_weak.as_ref().and_then(|w| w.upgrade()) {
                    Some(np) => {
                        let mut np_mut = np.borrow_mut();
                        if np_mut
                            .left_child_node
                            .as_ref()
                            .map_or(false, |n| Rc::ptr_eq(n, node))
                        {
                            np_mut.left_child_node = Some(Rc::clone(&candidate));
                        } else {
                            np_mut.right_child_node = Some(Rc::clone(&candidate));
                        }
                    }
                    None => {
                        self.root_node = Some(Rc::clone(&candidate));
                    }
                }
                candidate.borrow_mut().parent_node = node_parent_weak;
            }

            // Assign node's children to candidate
            {
                let node_left = { node.borrow().left_child_node.clone() };
                let node_right = { node.borrow().right_child_node.clone() };
                let node_left_count = { node.borrow().left_child_count };
                let node_right_count = { node.borrow().right_child_count };

                candidate.borrow_mut().left_child_node = node_left.clone();
                candidate.borrow_mut().left_child_count = node_left_count;
                candidate.borrow_mut().right_child_node = node_right.clone();
                candidate.borrow_mut().right_child_count = node_right_count;

                if let Some(ref lc) = node_left {
                    lc.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
                }
                if let Some(ref rc) = node_right {
                    rc.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
                }
            }

            // Rebalance from bubble_start up to candidate
            let same = Rc::ptr_eq(&bubble_start, node);
            if !same {
                let mut bs = Rc::clone(&bubble_start);
                loop {
                    let cand_ptr = Rc::as_ptr(&candidate);
                    let bs_ptr = Rc::as_ptr(&bs);
                    if bs_ptr == cand_ptr {
                        break;
                    }

                    // Update depth of bubble_start
                    {
                        let mut bs_mut = bs.borrow_mut();
                        let left_d = bs_mut
                            .left_child_node
                            .as_ref()
                            .map_or(0u32, |n| n.borrow().depth + 1);
                        let right_d = bs_mut
                            .right_child_node
                            .as_ref()
                            .map_or(0u32, |n| n.borrow().depth + 1);
                        bs_mut.depth = max(left_d, right_d);
                    }

                    let balance = bostree_balance(&bs.borrow());
                    if balance > 1 {
                        let right_child = { bs.borrow().right_child_node.clone() };
                        if let Some(ref rc) = right_child {
                            if bostree_balance(&rc.borrow()) < 0 {
                                rotate_right(self, rc);
                            }
                        }
                        bs = rotate_left(self, &bs);
                    } else if balance < -1 {
                        let left_child = { bs.borrow().left_child_node.clone() };
                        if let Some(ref lc) = left_child {
                            if bostree_balance(&lc.borrow()) > 0 {
                                rotate_left(self, lc);
                            }
                        }
                        bs = rotate_right(self, &bs);
                    }

                    // Move to parent
                    let next = match bs
                        .borrow()
                        .parent_node
                        .as_ref()
                        .and_then(|w| w.upgrade())
                    {
                        Some(p) => p,
                        None => break,
                    };
                    bs = next;
                }
            }

            // Fixup candidate's depth
            {
                let mut cand_mut = candidate.borrow_mut();
                let left_d = cand_mut
                    .left_child_node
                    .as_ref()
                    .map_or(0u32, |n| n.borrow().depth + 1);
                let right_d = cand_mut
                    .right_child_node
                    .as_ref()
                    .map_or(0u32, |n| n.borrow().depth + 1);
                cand_mut.depth = max(left_d, right_d);
            }

            // bubble_up = candidate's parent
            bubble_up = candidate
                .borrow()
                .parent_node
                .as_ref()
                .and_then(|w| w.upgrade());

            // Fix immediate parent node child count
            if let Some(ref bu) = bubble_up {
                let mut bu_mut = bu.borrow_mut();
                if bu_mut
                    .left_child_node
                    .as_ref()
                    .map_or(false, |n| Rc::ptr_eq(n, &candidate))
                {
                    bu_mut.left_child_count -= 1;
                } else {
                    bu_mut.right_child_count -= 1;
                }
            }
        } else {
            // Node has at most one child
            let node_parent = { node.borrow().parent_node.clone() };
            if node_parent.is_none() {
                // Node is root: replace root with its child
                let left = { node.borrow().left_child_node.clone() };
                let right = { node.borrow().right_child_node.clone() };
                if let Some(ref lc) = left {
                    self.root_node = Some(Rc::clone(lc));
                    lc.borrow_mut().parent_node = None;
                } else if let Some(ref rc) = right {
                    self.root_node = Some(Rc::clone(rc));
                    rc.borrow_mut().parent_node = None;
                } else {
                    self.root_node = None;
                }
                bubble_up = None;
            } else {
                let parent = node_parent.as_ref().and_then(|w| w.upgrade()).unwrap();
                let candidate = {
                    let n_ref = node.borrow();
                    if n_ref.left_child_node.is_some() {
                        n_ref.left_child_node.clone()
                    } else {
                        n_ref.right_child_node.clone()
                    }
                };
                let candidate_count = {
                    let n_ref = node.borrow();
                    if n_ref.left_child_node.is_some() {
                        n_ref.left_child_count
                    } else {
                        n_ref.right_child_count
                    }
                };

                {
                    let mut p_mut = parent.borrow_mut();
                    if p_mut
                        .left_child_node
                        .as_ref()
                        .map_or(false, |n| Rc::ptr_eq(n, node))
                    {
                        p_mut.left_child_node = candidate.clone();
                        p_mut.left_child_count = candidate_count;
                    } else {
                        p_mut.right_child_node = candidate.clone();
                        p_mut.right_child_count = candidate_count;
                    }
                }
                if let Some(ref c) = candidate {
                    c.borrow_mut().parent_node = Some(Rc::downgrade(&parent));
                }
                bubble_up = Some(Rc::clone(&parent));
            }
        }

        // Now bubble up to the root, updating depths and rebalancing
        let mut bubbling_finished = false;
        let mut bu_current = bubble_up;
        while let Some(bu) = bu_current.take() {
            if !bubbling_finished {
                let left_depth = bu
                    .borrow()
                    .left_child_node
                    .as_ref()
                    .map_or(0u32, |n| n.borrow().depth + 1);
                let right_depth = bu
                    .borrow()
                    .right_child_node
                    .as_ref()
                    .map_or(0u32, |n| n.borrow().depth + 1);
                let new_depth = max(left_depth, right_depth);
                let depth_changed = {
                    let bu_ref = bu.borrow();
                    new_depth != bu_ref.depth
                };
                {
                    let mut bu_mut = bu.borrow_mut();
                    bu_mut.depth = new_depth;
                }

                let balance = bostree_balance(&bu.borrow());
                if balance < -1 {
                    let left_child = { bu.borrow().left_child_node.clone() };
                    if let Some(ref lc) = left_child {
                        if bostree_balance(&lc.borrow()) > 0 {
                            rotate_left(self, lc);
                        }
                    }
                    let prev_ptr = Rc::as_ptr(&bu);
                    let new_bu = rotate_right(self, &bu);
                    // If the pointer changed, update bu to the new subtree root
                    if Rc::as_ptr(&new_bu) != prev_ptr {
                        bu_current = match new_bu
                            .borrow()
                            .parent_node
                            .as_ref()
                            .and_then(|w| w.upgrade())
                        {
                            Some(p) => Some(p),
                            None => break,
                        };
                        // Also need to decrement child count on parent
                        if let Some(ref next) = bu_current {
                            let mut next_mut = next.borrow_mut();
                            if next_mut
                                .left_child_node
                                .as_ref()
                                .map_or(false, |n| Rc::ptr_eq(n, &new_bu))
                            {
                                next_mut.left_child_count -= 1;
                            } else {
                                next_mut.right_child_count -= 1;
                            }
                        }
                        continue;
                    }
                    // Fall through to the move-to-parent case below
                } else if balance > 1 {
                    let right_child = { bu.borrow().right_child_node.clone() };
                    if let Some(ref rc) = right_child {
                        if bostree_balance(&rc.borrow()) < 0 {
                            rotate_right(self, rc);
                        }
                    }
                    let prev_ptr = Rc::as_ptr(&bu);
                    let new_bu = rotate_left(self, &bu);
                    if Rc::as_ptr(&new_bu) != prev_ptr {
                        bu_current = match new_bu
                            .borrow()
                            .parent_node
                            .as_ref()
                            .and_then(|w| w.upgrade())
                        {
                            Some(p) => Some(p),
                            None => break,
                        };
                        if let Some(ref next) = bu_current {
                            let mut next_mut = next.borrow_mut();
                            if next_mut
                                .left_child_node
                                .as_ref()
                                .map_or(false, |n| Rc::ptr_eq(n, &new_bu))
                            {
                                next_mut.left_child_count -= 1;
                            } else {
                                next_mut.right_child_count -= 1;
                            }
                        }
                        continue;
                    }
                    // Fall through
                } else if !depth_changed {
                    bubbling_finished = true;
                }
            }

            // Move to parent and decrement child count
            let parent_weak = { bu.borrow().parent_node.clone() };
            bu_current = parent_weak.as_ref().and_then(|w| w.upgrade());

            if let Some(ref next) = bu_current {
                let mut next_mut = next.borrow_mut();
                if next_mut
                    .left_child_node
                    .as_ref()
                    .map_or(false, |n| Rc::ptr_eq(n, &bu))
                {
                    next_mut.left_child_count -= 1;
                } else {
                    next_mut.right_child_count -= 1;
                }
            }
        }

        // Mark node as invalid and unref
        node.borrow_mut().weak_ref_node_valid = 0;
        self.bostree_node_weak_unref(node);
    }

    pub fn bostree_node_weak_unref(
        &mut self,
        node: &Rc<RefCell<BOSNode>>,
    ) -> Option<Rc<RefCell<BOSNode>>> {
        node.borrow_mut().weak_ref_count -= 1;
        if node.borrow().weak_ref_count == 0 {
            if let Some(ff) = self.free_function {
                ff(node);
            }
            None
        } else if node.borrow().weak_ref_node_valid != 0 {
            Some(Rc::clone(node))
        } else {
            None
        }
    }

    pub fn bostree_lookup(&self, key: &str) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        while let Some(node) = current {
            let cmp = (self.cmp_function)(key, &node.borrow().key);
            if cmp == 0 {
                return Some(Rc::clone(&node));
            } else if cmp < 0 {
                current = node.borrow().left_child_node.clone();
            } else {
                current = node.borrow().right_child_node.clone();
            }
        }
        None
    }

    pub fn bostree_select(&self, index: u32) -> Option<Rc<RefCell<BOSNode>>> {
        let mut node = self.root_node.clone();
        let mut idx = index;
        while let Some(current) = node {
            let left_count = { current.borrow().left_child_count };
            if left_count <= idx {
                idx -= left_count;
                if idx == 0 {
                    return Some(Rc::clone(&current));
                }
                idx -= 1;
                node = current.borrow().right_child_node.clone();
            } else {
                node = current.borrow().left_child_node.clone();
            }
        }
        None
    }

    #[cfg(debug_assertions)]
    pub fn bostree_print(&self) {
        if self.root_node.is_none() {
            return;
        }
        println!("digraph {{");
        println!("  ordering = out;");
        let root = Rc::clone(self.root_node.as_ref().unwrap());
        bostree_print_helper(&root);
        println!("}}");
    }
}

fn bostree_print_helper(node: &Rc<RefCell<BOSNode>>) {
    let n_ref = node.borrow();
    println!(
        "  {} [label=\"\\N ({},{},{})\"];",
        n_ref.key, n_ref.left_child_count, n_ref.right_child_count, n_ref.depth
    );
    if let Some(ref parent_weak) = n_ref.parent_node {
        if let Some(parent) = parent_weak.upgrade() {
            println!(
                "  {} -> {} [color=green];",
                n_ref.key,
                parent.borrow().key
            );
        }
    }
    if let Some(ref left) = n_ref.left_child_node {
        println!("  {} -> {}", n_ref.key, left.borrow().key);
        drop(n_ref);
        bostree_print_helper(left);
    }
    if let Some(ref right) = n_ref.right_child_node {
        // Need to re-borrow since we dropped above
        let n_ref2 = node.borrow();
        if let Some(ref right2) = n_ref2.right_child_node {
            println!("  {} -> {}", n_ref2.key, right2.borrow().key);
            drop(n_ref2);
            bostree_print_helper(right2);
        }
    }
}

pub fn bostree_node_weak_ref(node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    node.borrow_mut().weak_ref_count += 1;
    Rc::clone(node)
}

pub fn bostree_next_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    let n_ref = node.borrow();
    if let Some(ref right) = n_ref.right_child_node {
        let mut current = Rc::clone(right);
        loop {
            let next = { current.borrow().left_child_node.clone() };
            match next {
                Some(n) => current = n,
                None => return Some(current),
            }
        }
    } else if let Some(ref parent_weak) = n_ref.parent_node {
        drop(n_ref);
        let mut current = Rc::clone(node);
        loop {
            let parent = match current
                .borrow()
                .parent_node
                .as_ref()
                .and_then(|w| w.upgrade())
            {
                Some(p) => p,
                None => return None,
            };
            let is_right_child = parent
                .borrow()
                .right_child_node
                .as_ref()
                .map_or(false, |n| Rc::ptr_eq(n, &current));
            if !is_right_child {
                return Some(parent);
            }
            current = parent;
        }
    } else {
        None
    }
}

pub fn bostree_previous_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    let n_ref = node.borrow();
    if let Some(ref left) = n_ref.left_child_node {
        let mut current = Rc::clone(left);
        loop {
            let next = { current.borrow().right_child_node.clone() };
            match next {
                Some(n) => current = n,
                None => return Some(current),
            }
        }
    } else if let Some(ref parent_weak) = n_ref.parent_node {
        drop(n_ref);
        let mut current = Rc::clone(node);
        loop {
            let parent = match current
                .borrow()
                .parent_node
                .as_ref()
                .and_then(|w| w.upgrade())
            {
                Some(p) => p,
                None => return None,
            };
            let is_left_child = parent
                .borrow()
                .left_child_node
                .as_ref()
                .map_or(false, |n| Rc::ptr_eq(n, &current));
            if !is_left_child {
                return Some(parent);
            }
            current = parent;
        }
    } else {
        None
    }
}

pub fn bostree_rank(node: &Rc<RefCell<BOSNode>>) -> u32 {
    let mut counter = { node.borrow().left_child_count };
    let mut current = Rc::clone(node);
    loop {
        let parent = match current
            .borrow()
            .parent_node
            .as_ref()
            .and_then(|w| w.upgrade())
        {
            Some(p) => {
                let is_right_child = p
                    .borrow()
                    .right_child_node
                    .as_ref()
                    .map_or(false, |n| Rc::ptr_eq(n, &current));
                if is_right_child {
                    let left_count = { p.borrow().left_child_count };
                    counter += 1 + left_count;
                }
                p
            }
            None => break,
        };
        current = parent;
    }
    counter
}

